--
-- Структура таблицы `texts`
--

CREATE TABLE `texts` (
  `id_text` int NOT NULL,
  `text_field_ref` int NOT NULL,
  `text_type_ref` int NOT NULL,
  `value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `field_text_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS (concat(`text_field_ref`,_utf8mb4'_',`text_type_ref`)) VIRTUAL NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

