-- Дамп данных таблицы `texts`
--

INSERT INTO `texts` (`id_text`, `text_field_ref`, `text_type_ref`, `value`) VALUES
(777, 297, 1, 'Такси Алушта Симферополь аэропорт от 633 руб'),
(778, 298, 1, 'Заказать такси из Алушты в Симферополь или такси из Аэропорта Симферополя в Алушту очень удобно и быстро на сайте [domen]'),
(779, 299, 1, 'такси, алушта, ялта, симферополь, севастополь, керчь, балакла, утес, партенит, феодосия, судак, коктебель, евпатория, аэропорт, цена, стоимость'),
(780, 300, 1, 'Такси Алушта'),
(781, 301, 1, 'Такси Алушта-Симферополь аэропорт'),
(782, 302, 1, 'ЗАБРОНИРОВАТЬ ТАКСИ СЕЙЧАС'),
(783, 303, 1, 'Такси Алушта-Симферополь'),
(784, 304, 1, 'о нас'),
(785, 305, 1, 'ТАКСИ АЛУШТА, СИМФЕРОПОЛЬ'),
(786, 306, 1, '<p>Если Вы еще не решили где заказать такси из Алушты в аэропорт Симферополя или Анапы? Тогда звоните нам по телефону [phone]. Наша компания \"Такси Алушта 24\" обладает рядом преимуществ перед другими перевозчиками и службами такси. Благодаря именно этим преимуществам, мы можем предоставить клиентам по-настоящему качественный сервис:</p>\r\n\r\n          <ul class=\"check two-col strong\">\r\n            <li>Свой автопарк</li>\r\n            <li>Большой выбор автомобилей</li>\r\n            <li>Опытные водители</li>\r\n            <li>Хорошее знание маршрута</li>\r\n            <li>Возможность оплаты по безналу</li>\r\n            <li>Быстрая доставка</li>\r\n          </ul>\r\n          <p>Обращаясь к нам, клиент может быть уверен, что его доставят по нужному адресу максимально быстро и комфортно. Сюда, кстати, следует добавить также, и безопасно. Ведь именно безопасность пассажиров является главным приоритетом наших водителей</p>'),
(787, 307, 1, '<p>\r\n                      Когда возникает необходимость поездки в другой город, большинство из нас задумываются о том, где в этом городе можно остановиться, какое временное жилье снять, что будет более актуально – гостиница или квартира посуточно. Но на самом деле, помимо вышеупомянутых вопросов есть еще один, который точно нельзя игнорировать. Это вопрос транспортировки. От аэропорта Симферополя или Анапы до гостиницы в Алуште нужно как-то доехать. И в данном случае оптимальным решением будет обратиться в такси. Сейчас есть масса перевозчиков, но далеко не все они предоставляют свою услугу одинаково качественно. Преимуществами непосредственно нашей компании являются:\r\n                    </p>  \r\n                    <ul class=\"check two-col strong\">\r\n                        <li>Узкая специализация по маршрутам</li>\r\n                        <li>Большой автопарк</li>\r\n                        <li>Квалификация водителей</li>\r\n                        <li>Опыт водителей</li>\r\n                      </ul>\r\n                    <p>\r\n                      В первую очередь нужно отметить специализацию по маршрутам. Точнее, по маршрутам, позволяющим максимально быстро и безопасно достичь пункта назначения. Поскольку мы осуществляем перевозки сугубо между Алуштой и Симферополем, можно с уверенностью сказать, что наши водители знают все маршруты между этими точками. А значит, если случится ситуация, когда один из участков дороги будет закрыт на ремонт, или вдруг где-то образуется затор, наши водители легко сориентируются и найдут выход из ситуации.\r\n                    </p>\r\n                      <p>Что касательно автопарка, следует отметить, что у нас есть различные автомобили. Нашими клиентами могут быть как бизнесмены, путешествующие самостоятельно, так и семьи, приехавшие в отпуск. Соответственно, а нас можно заказать как небольшой седан, так и минивен, и даже микроавтобус, если речь идет о поездке делегации из 10 человек. Благодаря столь обширному автопарку, мы можем легко обслужить любых пассажиров.</p>\r\n                      <p>Ну и наконец, стоит отметить квалификацию наших водителей. Благодаря опыту вождения, они могут обеспечить наиболее безопасную транспортировку. Главный приоритет водителей во время езды, это безопасность клиентов. И многочисленные положительные отзывы от наших пассажиров, являются лучшим тому подтверждением. В то время, как другие службы такси ставят в приоритет максимально быстро привезти пассажира в нужный пункт, чтобы сократить время поездки и выполнить больше заказов, наше такси в приоритете имеет безопасность клиента. Стоит отметить, что это не в ущерб времени поездки на такси из аэропорта Симферополя в Алушту. Поэтому с каждым месяцем все больше клиентов обращаются к нам, чтобы доехать из аэропорта в гостиницу и обратно. Поэтому, если планируете поездку в Алушту – обратите внимание на нашу службу такси, и вы можете быть уверены в том, что доберетесь до нужного места вовремя, и безопасно.</p>'),
