(821, 342, 1, 'Спасибо за помощь с багажом. Ваши водители самые лучшие.'),
(822, 343, 1, 'Евгения Андропока'),
(823, 344, 1, 'Евгения, клиент нашего Такси'),
(824, 345, 1, 'Благодарю за терпение. Несмотря на то, что рейс задержался, автомобиль меня ждал до победного конца.'),
(825, 346, 1, 'Михаил Сергеев'),
(826, 347, 1, 'Михаил, клиент Такси из Симферополя в Алушту'),
(827, 348, 1, 'Спасибо больше! Рейс задержался, но меня всё равно ждали, очень приятно, уровень!'),
(828, 349, 1, 'Максим Иванченко'),
(829, 350, 1, 'Максим, клиент Такси Алушта 24'),
(830, 351, 1, 'Такси из Алушты в Симферополь'),
(831, 352, 1, 'Наши водители \"Такси Алушта 24\" рады работать с любыми пассажирами. Неважно, путешествуете ли вы самостоятельно, с деловым партнером, или с многодетной семьей – в любом случае вам подберут автомобиль, который соответствует вашим потребностям и ожиданиям. И, конечно же, наши приветливые водители всегда проявят максимум такта и вежливости.'),
(832, 353, 1, 'наши контакты'),
(833, 354, 1, '[year] © Такси Алушта, Симферополь'),
(834, 355, 1, 'Политика конфиденциальности'),
(835, 356, 1, '<p>Нам очень важна конфиденциальность Вашей информации. Личные данные, которые Вы доверяете нам, заполняя форму заявки на сайте https://alushta24.taxi , будут использованы с целью подготовки Услуг в соответствии с Вашими основными требованиями.</p>\r\n<p>Передача Вашей информации третьим лицам полностью исключена.</p>\r\n<p>Какие данные собираются на сайте: При добровольном заполнении формы заявки Вы отправляете нам: свое Имя, свой Телефон и свой E-mail.</p>'),
(836, 357, 1, 'Точную стоимость уточняйте у диспетчера! Акция ограничена количеством автомобилей.'),
(1257, 297, 2, 'Такси Алушта - [city_2_im] от [title_price] руб'),
(1258, 298, 2, 'Заказать такси из Алушты в [city_2_vin] удобно и  очень быстро по телефону [phone]. Такси из Алушты с хорошим комфортом доставят вас по адресу в [city_2_vin] своевременно и недорого'),
(1259, 299, 2, 'такси, алушта, ялта, симферополь, Алушта, керчь, балакла, утес, партенит, феодосия, судак, коктебель, евпатория, аэропорт, цена, стоимость'),
