(1266, 306, 2, '<p>Заказав такси из Алушты в [city_2_vin] по телефону [phone], вы совершите безошибочный выбор службы, которая доставит вас к месту следования точно в срок с максимальным комфортом и безопасностью. Главный фактор, который выгодно отличает нашу компанию от множества подобных, - индивидуальный подход к каждому клиенту. При заказе такси Алушта - [city_2_im] диспетчер учитывает абсолютно все пожелания и требования клиента: от выбора марки и цвета автомобиля, до составления индивидуального маршрута. Само собой разумеется, что необходимость наличия детского кресла или же вместительного багажника также учитываются. Преимуществами  нашей компании:</p>\r\n          <ul class=\"check two-col strong\">\r\n            <li>Быстрая обслуживание клиентов</li>\r\n            <li>Свой автопарк машин</li>\r\n            <li>Большой выбор автомобилей</li>\r\n            <li>Опытные водители</li>\r\n            <li>Хорошее знание маршрута</li>\r\n            <li>Предоставим детское кресло</li>\r\n           </ul>\r\n          <p>Наши водители всегда готовы подождать клиента, если он задерживается, а при\r\nнеобходимости – помогут с погрузкой и разгрузкой багажа.  И никаких проблем\r\nс поиском сдачи или размена.</p>'),
(1267, 307, 2, '<p><a href=\"[main_url]\" style=\"color:black\">Вызывая такси в [city_2_vin] из Алушты</a>, вы можете быть абсолютно спокойны и не бояться за свою безопасность. В нашей компании работают исключительно опытные водители, за\r\nплечами которых не одна тысяча наезженных километров. Они всегда умело выбирают\r\nнаиболее удобный для клиента путь следования. И если вам по пути необходимо побывать\r\nв нескольких местах – можете быть уверенны, водитель выберет наиболее безопасный и\r\nбыстрый маршрут, при этом он заранее исключит из него те отрезки пути, где возможны\r\nпробки или «тянучки».</p>'),
