(1311, 352, 2, 'Если вы еще не определились, какая служба такси вас устраивает – вызывайте наше такси  из Алушты в [city_2_vin] по телефону [phone], и тогда вы гарантировано сэкономите время,\r\nденьги и, что немаловажно, нервы.  Все машины автопарка находятся в исправном состоянии, своевременно проходят техосмотр, чем обеспечивается высокая безопасность пассажиров'),
