(1805, 305, 3, 'ТАКСИ ИЗ [city_1_rod] В АЛУШТУ'),
(1806, 306, 3, '<p>Вам обходимо добраться на такси из [city_1_rod] в Алушту, и вы не знаете, услугами какой\r\nслужбы такси воспользоваться? Позвоните по телефону [phone] или же оформите заказ на нашем сайте, и вы поймете, что такси [city_1_im] - Алушта – это то, что вам\r\nнужно. Индивидуальный подход к каждому заказу, свой автопарк, большой выбор автомобилей,\r\nопытные водители, быстрая доставка, приятные цены, возможность оплаты по безналу – и\r\nэто далеко не все преимущества нашей компании перед другими подобными фирмами.:</p>\r\n\r\n          <ul class=\"check two-col strong\">\r\n            <li>Свой автопарк</li>\r\n            <li>Большой выбор автомобилей</li>\r\n            <li>Опытные водители</li>\r\n            <li>Хорошее знание маршрута</li>\r\n            <li>Предоставим детское кресло</li>\r\n            <li>Быстрая доставка</li>\r\n          </ul>\r\n          <p>Мы дорожим каждым клиентом и стараемся сделать каждую поездку приятной и\r\nкомфортной. Воспользовавшись услугами, вы можете забыть обо всех заботах, связанных\r\nс дорогой. Маршрут следования, помощь в погрузке или разгрузке багажа и ваши комфорт\r\nи безопасность - все это мы берем на себя.</p>'),
(1807, 307, 3, '<p>При заказе диспетчер обязательно уточнит количество пассажиров, объем багажа и будут ли с вами дети. Эта информация необходима для того, чтобы сделать максимально удачный выбор автомобиля. И даже если у вас есть какие-либо предпочтения по маршруту следования – сообщите об этом нам, и мы обязательно составим для вас индивидуальный маршрут.</p>\r\n<p> Наши водители полностью берут на себя заботу о безопасности пассажиров.<a href=\"[main_url]\" style=\"color:black\" > В такси в Алушту из [city_1_rod]</a>  вы можете не опасаться за свою жизнь и здоровье. Каждый из наших водителей прекрасно знает все возможные маршруты и поэтому они способны заранее предугадать вероятность создания любых внештатных ситуаций, и успешно избегают их.</p>'),
