(2606, 326, 4, 'Мы занимается междугородними перевозками, наши водители знают оптимальный маршрут между городами'),
(2607, 327, 4, ''),
(2608, 328, 4, 'Безопасность'),
(2609, 329, 4, 'Квалификация наших водителей, это гарантия безопасности поездки'),
(2610, 330, 4, ''),
(2611, 331, 4, 'Направления'),
(2612, 332, 4, 'Отвезем в [city_2_vin] или в другой город Крыма'),
(2613, 333, 4, ''),
(2614, 334, 4, 'Сервис'),
(2615, 335, 4, 'Наши водители помогут с погрузкой и разгрузкой багажа, не взяв за это отдельную плату'),
(2616, 337, 4, 'Отзывы'),
(2617, 338, 4, 'Счастливых клиентов'),
(2618, 339, 4, 'Поездка из [city_1_rod] в [city_2_vin] заняла намного меньше времени, чем требуется, благодаря опытному водителю. Сразу было видно, что он профессионал, потому что выбирал короткие маршруты.'),
(2619, 340, 4, 'Ирина Смирнова'),
(2620, 341, 4, 'Ирина, клиент Такси 24 в [city_2_vin]'),
(2621, 342, 4, 'Спасибо за качественный сервис. Уже больше месяца пользуюсь такси. Особенно актуально приехать домой после вечеринок. Машина всегда приезжает вовремя.'),
(2622, 343, 4, 'Евгения Андропока'),
(2623, 344, 4, 'Евгения, клиент нашего Такси'),
(2624, 345, 4, 'Ехал из [city_1_rod] в [city_2_vin] с большим багажом. Сразу предупредил об этом диспетчера, он с учетом моих потребностей предоставил просторную машину – минивэн.'),
(2625, 346, 4, 'Михаил Сергеев'),
(2626, 347, 4, 'Михаил, клиент Такси из [city_1_rod]'),
(2627, 348, 4, 'Очень понравилось обслуживание. Вежливый диспетчер своевременно отвечал на вопросы и подобрал подходящий маршрут. А водитель включал в машине хорошую музыку.'),
(2628, 349, 4, 'Максим Иванченко'),
(2629, 350, 4, 'Максим, клиент в [city_2_vin]'),
(2630, 351, 4, 'Недорогое такси из [city_1_rod] в [city_2_vin]'),
(2631, 352, 4, 'Если вы еще не определились, какая служба такси вас устраивает – вызывайте наше такси  из [city_1_rod] в [city_2_vin] по телефону [phone], и тогда вы гарантировано сэкономите время, деньги и, что немаловажно, нервы.  Все машины автопарка находятся в исправном состоянии, своевременно проходят техосмотр, чем обеспечивается высокая безопасность пассажиров'),
(2632, 353, 4, 'наши контакты'),
(2633, 354, 4, '[year] © Такси [city_1_im], [city_2_im]'),
(2634, 355, 4, 'Политика конфиденциальности'),
(2635, 356, 4, '<p>Нам очень важна конфиденциальность Вашей информации. Личные данные, которые Вы доверяете нам, заполняя форму заявки на сайте https://alushta24.taxi , будут использованы с целью подготовки Услуг в соответствии с Вашими основными требованиями.</p>\r\n<p>Передача Вашей информации третьим лицам полностью исключена.</p>\r\n<p>Какие данные собираются на сайте: При добровольном заполнении формы заявки Вы отправляете нам: свое Имя, свой Телефон и свой E-mail.</p>'),
(2636, 357, 4, 'Точную стоимость уточняйте у диспетчера! Акция ограничена количеством автомобилей.'),
(2877, 297, 5, 'Трансфер [city_1_im] - [city_2_im] от [title_price] руб'),
(2878, 298, 5, 'Заказать трансфер из [city_1_rod] в [city_2_vin] очень удобно и быстро на сайте или по тел. [phone]. Недорогой трансфер из [city_1_rod] с высоким комфортом доставит вас по адресу в [city_2_vin]'),
(2879, 299, 5, 'трансфер, алушта, ялта, симферополь, Алушта, керчь, балакла, утес, партенит, феодосия, судак, коктебель, евпатория, аэропорт, цена, стоимость'),
(2880, 300, 5, 'Трансфер из [city_1_rod] в [city_2_vin]'),
(2881, 301, 5, 'Трансфер [city_1_im] - [city_2_im]'),
(2882, 302, 5, 'ЗАБРОНИРОВАТЬ ТРАНСФЕР ИЗ [city_1_rod]'),
(2883, 303, 5, 'Недорогой трансфер [city_1_im] - [city_2_im]'),
(2884, 304, 5, 'о нас'),
(2885, 305, 5, 'ТРАНСФЕР ИЗ [city_1_rod] в [city_2_vin]'),
(2886, 306, 5, '<p>Перемещение по полуострову Крым облегчается благодаря нашей службе. У нас на сайте  можно заказать трансфер [city_1_im] - [city_2_im]. Ваше путешествие по разным городам Крыма будет проходить с комфортом, а также индивидуальным подходом к каждому пассажиру. Заказать такси можно по телефону, и на сайте, заполнив короткую форму на главной странице. Безопасность клиентов превыше всего, поэтому все автомобили проходят ежегодную проверку на исправность. Диспетчер мгновенно реагирует на заявки и пришлет за вами автомобиль, который доставит в необходимое место быстро и безопасно.</p>\r\n<p><strong>Выгода от пользования такси. </strong></p>\r\n<p>Трансфер [city_1_im] - [city_2_im]  с помощью удобного сервиса – это один из главных и востребованных видов перемещения, превосходящий общественный транспорт. </p>'),
(2887, 307, 5, '<ul>\r\n<li>Безупречная репутация. Компания заслужила доверие из-за ежедневных перевозок, после которых клиенты остаются довольны обслуживанием. На сайте можно посмотреть оценки и отзывы от пользователей. </li>\r\n<li>Абсолютная безопасность. Компания несет ответственность за перевозку пассажиров и дает гарантию полного комфорта. В наличии автопарка есть представительские VIP такси, такие как Мерседес S класса и Мерседес Е -212. Все эконом и бизнес автомобили всегда в отличном техническом состоянии, а водители заботятся о самочувствии пассажиров. </li>\r\n<li>Скорость поездки. Сервис такси не терпит отклонений от графика и промедлений, поэтому если вам нужно срочно добраться до определенного места, то водители компании в этом помогут. Время подачи авто быстрое и не заставит себя долго ждать. </li>\r\n</ul>'),
(2888, 308, 5, 'Тарифы на трансфер по Крыму'),
(2889, 309, 5, 'Посмотрите стоимость проезда по основным городам Крыма в [year] году'),
(2890, 310, 5, 'Узнать точную стоимость'),
(2891, 311, 5, 'класс машин в трансфере'),
(2892, 312, 5, 'выберите свой'),
