(2909, 329, 5, 'Наши водители помогут с погрузкой и разгрузкой багажа, не взяв за это отдельную плату'),
(2910, 330, 5, ''),
(2911, 331, 5, 'Направления'),
(2912, 332, 5, 'Наши водители помогут с погрузкой и разгрузкой багажа, не взяв за это отдельную плату'),
(2913, 333, 5, ''),
(2914, 334, 5, 'Сервис'),
(2915, 335, 5, 'Наши водители помогут с погрузкой и разгрузкой багажа, не взяв за это отдельную плату'),
(2916, 337, 5, 'Отзывы'),
(2917, 338, 5, 'Счастливых клиентов'),
(2918, 339, 5, 'Удивилась, когда увидела цену на машину вип класса. Сразу же ее и заказал, ведь она обошлась мне очень дешево. На место приехал презентабельных мерседес с безупречно чистым салоном.'),
(2919, 340, 5, 'Ирина Смирнова'),
(2920, 341, 5, 'Ирина, клиент, который заказывала трансфер [city_2_vin]'),
(2921, 342, 5, 'Заказывала трансфер из [city_1_rod] в [city_2_vin], связавшись с диспетчером компании. Машину доставили точно в срок и такую, как я хотела. Поездкой довольна из-за опытности водителя.'),
(2922, 343, 5, 'Евгения Андропока'),
(2923, 344, 5, 'Евгения, пользуется услугами трансфера'),
(2924, 345, 5, 'Трансфер из [city_1_rod] в [city_2_vin] прошел на удивление быстро и без задержек. Не ожидал такого высокого обслуживания. Теперь я постоянно заказываю трансфер на сервисе.'),
(2925, 346, 5, 'Михаил Сергеев'),
(2926, 347, 5, 'Михаил, заказал трансфер из [city_1_rod]'),
(2927, 348, 5, 'Ездили с друзьями отдыхать в [city_2_vin]. На 6 человек прислали минивен. Доставили четко к оговоренному месту быстро и комфортно. Все остались довольны. Спасибо!'),
(2928, 349, 5, 'Максим Иванченко'),
(2929, 350, 5, 'Максим, клиент в [city_2_vin]'),
(2930, 351, 5, 'Недорогой трансфер из [city_1_rod] в [city_2_vin]'),
(2931, 352, 5, 'Служба трансфера устанавливает фиксированные цены на услуги. Никаких доплат не предусматривается, поэтому поездка обойдется недорого. Также все автомобили оборудованы кондиционером, включая эконом класс. Пассажир заранее обсуждает с водителем план маршрута. Он всегда останавливает машину по необходимости. </p>\r\n<p>Мы с радостью предоставим вам <a href=\"[direction_url]\" style=\"color:white\">такси [city_1_im]  [city_2_im]</a>.'),
(2932, 353, 5, 'наши контакты'),
(2933, 354, 5, '[year] © Трансфер [city_1_im], [city_2_im]'),
(2934, 355, 5, 'Политика конфиденциальности'),
(2935, 356, 5, '<p>Нам очень важна конфиденциальность Вашей информации. Личные данные, которые Вы доверяете нам, заполняя форму заявки на сайте https://alushta24.taxi , будут использованы с целью подготовки Услуг в соответствии с Вашими основными требованиями.</p>\r\n<p>Передача Вашей информации третьим лицам полностью исключена.</p>\r\n<p>Какие данные собираются на сайте: При добровольном заполнении формы заявки Вы отправляете нам: свое Имя, свой Телефон и свой E-mail.</p>'),
(2936, 357, 5, 'Точную стоимость уточняйте у диспетчера! Акция ограничена количеством автомобилей.');

